/// <summary>
/// Extension of filterLookupPostRun method
/// </summary>
/// <param name = "_isFiltered">boolean</param>
/// <param name = "_filterString">str</param>
/// <param name = "_controlToFilter">FormStringControl</param>
/// <param name = "_formDataSource">FormDataSource</param>
/// <param name = "_referenceResolver">FormControlAmbiguousReferenceResolver</param>
/// <param name = "_alternativeFieldControl">FormStringControl</param>
/// <param name = "_addOrderByForAlternativeFieldIfRequired">boolean</param>
public static void filterLookupPostRun(boolean _isFiltered,
                                       str _filterString,
                                       FormStringControl _controlToFilter,
                                       FormDataSource _formDataSource,
                                       FormControlAmbiguousReferenceResolver _referenceResolver,
                                       FormStringControl _alternativeFieldControl,
                                       boolean _addOrderByForAlternativeFieldIfRequired)
{
    next filterLookupPostRun(_isFiltered, _filterString, _controlToFilter, _formDataSource, _referenceResolver, _alternativeFieldControl, _addOrderByForAlternativeFieldIfRequired);

    switch(_controlToFilter.formRun().name())
    {
        case formStr(InventItemIdLookupSimple):
        case formStr(LogisticsAddressZipCodeLookup)  :
            _formDataSource.removeFilter();
            break;

        default:
            break;
    }
}

/// <summary>
/// Updates the system-generated filters for an already open lookup form.
/// </summary>
/// <param name = "_formRun">The lookup form that is to have its filters updated.</param>
/// <param name = "_filterValue">The updated filter value.</param>
public static void applyUpdatedFilterToLookup(FormRun _formRun, str _filterValue)
{
    next applyUpdatedFilterToLookup(_formRun, _filterValue);

    switch(_formRun.name())
    {
        case formStr(InventItemIdLookupSimple):
            _formRun.dataSource('InventItemIdLookupSimpleView').removeFilter();
            break;

        case formStr(LogisticsAddressZipCodeLookup):
            _formRun.dataSource('ZipCode').removeFilter();
            break;

        default:
            break;
    }
}
